import { z } from 'zod';
import { ACTIONS, CATEGORIES, CLASSIFICATIONS, SEVERITIES, SOURCE_TYPES } from '../detection/constants.js';

export const deviceIdSchema = z
  .string()
  .trim()
  .regex(/^[A-Za-z0-9_-]{3,64}$/, 'must be 3-64 characters: letters, digits, "-" or "_"');

const ipSchema = z.union([z.ipv4(), z.ipv6()]);

const headersSchema = z
  .record(z.string().min(1).max(64), z.string().max(1024))
  .refine((headers) => Object.keys(headers).length <= 30, 'at most 30 headers');

/**
 * Event report accepted from devices (and generated by the simulator). Unknown keys are
 * stripped, so client-supplied severity/classification/actionTaken/simulated values and any
 * password or body fields are discarded before processing.
 */
export const ingestEventSchema = z.object({
  deviceId: deviceIdSchema,
  clientIp: ipSchema.optional(),
  sourceIdentifier: z.string().trim().min(1).max(128).optional(),
  method: z
    .string()
    .trim()
    .min(1)
    .max(16)
    .regex(/^[A-Za-z][A-Za-z_-]*$/, 'must be an HTTP method token')
    .transform((method) => method.toUpperCase()),
  path: z.string().min(1).max(2048),
  query: z.string().max(2048).optional(),
  responseStatus: z.int().min(100).max(599).optional(),
  userAgent: z.string().max(512).optional(),
  loginResult: z.enum(['success', 'failed']).optional(),
  headers: headersSchema.optional(),
  bodyBytes: z.int().min(0).max(100_000_000).optional(),
  uptimeMs: z.int().min(0).optional(),
  observedAt: z.iso.datetime({ offset: true }).optional(),
  correlationId: z
    .string()
    .regex(/^[A-Za-z0-9_.:-]{8,64}$/, 'must be 8-64 characters: letters, digits, "_", ".", ":" or "-"')
    .optional(),
});

export const registerDeviceSchema = z.object({
  deviceId: deviceIdSchema,
  name: z.string().trim().min(1).max(80).optional(),
  hardware: z.string().trim().min(1).max(64).optional(),
  firmwareVersion: z.string().trim().min(1).max(32).optional(),
  ipAddress: ipSchema.optional(),
});

export const heartbeatSchema = z.object({
  deviceId: deviceIdSchema,
  firmwareVersion: z.string().trim().min(1).max(32).optional(),
  ipAddress: ipSchema.optional(),
  rssi: z.int().min(-127).max(0).optional(),
  uptimeMs: z.int().min(0).optional(),
  freeHeap: z.int().min(0).max(10_000_000).optional(),
});

export const RANGES = ['15m', '1h', '24h', '7d', 'all'];

const commaList = (values) =>
  z
    .string()
    .max(200)
    .transform((value) => value.split(',').map((item) => item.trim()).filter(Boolean))
    .pipe(z.array(z.enum(values)).max(values.length));

export const rangeQuerySchema = z.object({
  range: z.enum(RANGES).default('24h'),
  sourceType: z.enum(SOURCE_TYPES).optional(),
  // Minutes to add to UTC to get local time (i.e. -Date.getTimezoneOffset()); aligns day buckets.
  tzOffset: z.coerce.number().int().min(-840).max(840).default(0),
});

export const EVENT_SORT_FIELDS = [
  'timestamp',
  'severity',
  'method',
  'path',
  'category',
  'sourceIdentifier',
  'sourceType',
  'actionTaken',
  'responseStatus',
];

export const listEventsQuerySchema = z.object({
  page: z.coerce.number().int().min(1).max(100000).default(1),
  limit: z.coerce.number().int().min(1).max(100).default(25),
  search: z.string().trim().max(100).optional(),
  severity: commaList(SEVERITIES).optional(),
  category: commaList(CATEGORIES).optional(),
  classification: commaList(CLASSIFICATIONS).optional(),
  actionTaken: commaList(ACTIONS).optional(),
  sourceType: commaList(SOURCE_TYPES).optional(),
  deviceId: deviceIdSchema.optional(),
  range: z.enum(RANGES).default('all'),
  sort: z.enum(EVENT_SORT_FIELDS).default('timestamp'),
  order: z.enum(['asc', 'desc']).default('desc'),
});

export const objectIdParamSchema = z.object({
  id: z.string().regex(/^[a-f0-9]{24}$/i, 'must be a valid id'),
});

export const deviceIdParamSchema = z.object({ id: deviceIdSchema });
